<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from 'vue'
const nodes=[{name:'Input Queue',x:35,y:90,c:'#60a5fa'},{name:'Decode',x:220,y:35,c:'#38bdf8'},{name:'ALU',x:405,y:35,c:'#fbbf24'},{name:'Commit',x:590,y:90,c:'#c084fc'},{name:'Load/Store',x:313,y:160,c:'#2dd4bf'}]
const paths=[['M145 115 C175 115 180 60 220 60'],['M330 60 H405'],['M515 60 C555 60 555 115 590 115'],['M275 85 C275 150 300 185 313 185'],['M423 185 C510 185 520 115 590 115']]
const stepIndex=ref(0),playing=ref(false);let timer:ReturnType<typeof setInterval>|undefined
const currentPath=computed(()=>stepIndex.value%paths.length)
function step(){stepIndex.value=(stepIndex.value+1)%paths.length}function stop(){playing.value=false;if(timer)clearInterval(timer);timer=undefined}function play(){if(playing.value)return;playing.value=true;timer=setInterval(step,900)}function reset(){stop();stepIndex.value=0}onBeforeUnmount(stop)
</script>
<template>
 <section class="flow"><header><div><small>QUEUE-WIRED MODEL</small><h3>Data moves; modules react.</h3></div><div><button @click="step">Step</button><button @click="playing?stop():play()">{{playing?'Pause':'Play'}}</button><button @click="reset">Reset</button></div></header>
 <svg viewBox="0 0 735 245"><defs><marker id="arr" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0l10 5-10 5z" fill="#60738e"/></marker></defs><path v-for="(p,i) in paths" :key="p[0]" :d="p[0]" :class="{active:i===currentPath}" marker-end="url(#arr)"/><g v-for="(n,i) in nodes" :key="n.name"><rect :x="n.x" :y="n.y" width="110" height="50" rx="9" :style="{stroke:n.c}"/><text :x="n.x+55" :y="n.y+30">{{n.name}}</text><circle v-if="i===currentPath || i===currentPath+1" :cx="n.x+12" :cy="n.y+12" r="4" :fill="n.c"/></g><circle class="packet" r="6"><animateMotion :dur="playing?'.9s':'999s'" repeatCount="indefinite" :path="paths[currentPath][0]"/></circle></svg>
 <footer><span>cycle {{ String(stepIndex+1).padStart(2,'0') }}</span><p><b>Invariant:</b> transfers occur only when <code>valid &amp;&amp; ready</code>.</p><span class="live">● LIVE</span></footer></section>
</template>
